// PDF rendering by an installed Chromium/Chrome (no npm dependency). The app stays fully usable without it:
// when no browser is found the export route answers 501 and the screen offers the browser's own "Save as PDF".
//
// The page that is printed is generated by the server from escaped content, carries a CSP that forbids
// script and network access, and is printed by a throw-away browser profile with name resolution disabled.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { AppError } from './errors.js';

export const pdfUnavailable = () => new AppError(501, 'pdf_unavailable', 'PDF export unavailable', 'PDF export needs Chromium or Chrome on this computer (set CHROMIUM_PATH). Use the browser\'s Print > Save as PDF instead.');

const SYSTEM_CANDIDATES = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome', '/usr/bin/google-chrome-stable'];

/** An explicit path is used as given (never silently replaced); otherwise look in the usual places. */
export function findChromium({ explicit = null, env = process.env } = {}) {
  const usable = (p) => {
    try {
      fs.accessSync(p, fs.constants.X_OK);
      return fs.statSync(p).isFile();
    } catch {
      return false;
    }
  };
  if (explicit) return usable(explicit) ? explicit : null;
  if (env.CHROMIUM_PATH) return usable(env.CHROMIUM_PATH) ? env.CHROMIUM_PATH : null;
  const bases = [env.PLAYWRIGHT_BROWSERS_PATH, '/opt/pw-browsers'].filter(Boolean);
  for (const base of bases) {
    try {
      for (const d of fs.readdirSync(base).filter((x) => /^chromium-\d+$/.test(x)).sort().reverse()) {
        const p = path.join(base, d, 'chrome-linux', 'chrome');
        if (usable(p)) return p;
      }
    } catch {
      /* not there */
    }
  }
  return SYSTEM_CANDIDATES.find(usable) ?? null;
}

export function createPdfRenderer({ chromiumPath = null, timeoutMs = 30000, maxConcurrent = 2, maxQueued = 4, cacheSize = 32 } = {}) {
  const exe = findChromium({ explicit: chromiumPath });
  const cache = new Map(); // key -> Buffer; keys include the content fingerprint, so an entry can never serve changed content
  let running = 0;
  const waiting = [];

  const acquire = () =>
    new Promise((resolve, reject) => {
      if (running < maxConcurrent) {
        running++;
        return resolve();
      }
      if (waiting.length >= maxQueued) return reject(new AppError(429, 'pdf_busy', 'Busy', 'Several PDFs are being prepared. Try again in a moment.'));
      waiting.push(resolve);
    });
  const release = () => {
    const next = waiting.shift();
    if (next) next();
    else running--;
  };

  async function print(html) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-pdf-'));
    try {
      const input = path.join(dir, 'report.html');
      const output = path.join(dir, 'report.pdf');
      fs.writeFileSync(input, html, { mode: 0o600 });
      const args = [
        '--headless',
        '--disable-gpu',
        '--disable-extensions',
        '--disable-dev-shm-usage',
        '--disable-background-networking',
        '--disable-component-update',
        '--no-first-run',
        '--host-resolver-rules=MAP * ~NOTFOUND', // nothing in the page can reach the network
        `--user-data-dir=${path.join(dir, 'profile')}`,
        '--no-pdf-header-footer',
        `--print-to-pdf=${output}`,
        ...(process.getuid?.() === 0 ? ['--no-sandbox'] : []), // Chromium refuses to start as root otherwise
        `file://${input}`,
      ];
      await new Promise((resolve, reject) => {
        const child = spawn(exe, args, { stdio: 'ignore', env: { PATH: process.env.PATH, HOME: dir, LANG: 'C.UTF-8' } });
        const timer = setTimeout(() => {
          child.kill('SIGKILL');
          reject(new AppError(502, 'pdf_failed', 'PDF failed', 'The PDF took too long to prepare.'));
        }, timeoutMs);
        child.on('error', () => {
          clearTimeout(timer);
          reject(new AppError(502, 'pdf_failed', 'PDF failed', 'The PDF could not be prepared.'));
        });
        child.on('exit', () => {
          clearTimeout(timer);
          resolve();
        });
      });
      let pdf;
      try {
        pdf = fs.readFileSync(output);
      } catch {
        throw new AppError(502, 'pdf_failed', 'PDF failed', 'The PDF could not be prepared.');
      }
      if (pdf.subarray(0, 5).toString('latin1') !== '%PDF-') throw new AppError(502, 'pdf_failed', 'PDF failed', 'The PDF could not be prepared.');
      return pdf;
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  }

  return {
    available: () => Boolean(exe),
    /** `cacheKey` must change whenever the printed content or its language could differ. */
    async render(html, cacheKey) {
      if (!exe) throw pdfUnavailable();
      if (cacheKey && cache.has(cacheKey)) return cache.get(cacheKey);
      await acquire();
      try {
        const pdf = await print(html);
        if (cacheKey) {
          if (cache.size >= cacheSize) cache.delete(cache.keys().next().value);
          cache.set(cacheKey, pdf);
        }
        return pdf;
      } finally {
        release();
      }
    },
  };
}
